const app=document.getElementById('app');
const defaults={games:[{icon:'⛏️',name:'Minecraft',meta:'Java + Bedrock'},{icon:'🟥',name:'Roblox',meta:'Games & experiences'},{icon:'🥽',name:'Friends & Scares',meta:'Meta Quest 3S'}],servers:[{id:1,name:'WhiteBoardSMP',address:'Add your server IP',version:'1.21.x',edition:'Java + Bedrock',favorite:true},{id:2,name:'FriendsSMP',address:'Add your server IP',version:'1.21.x',edition:'Java + Bedrock',favorite:false}],friends:[],profile:{name:'Robbie',status:'Ready to play',bio:'Welcome to my GameHub profile!'}};
function read(k){try{return JSON.parse(localStorage.getItem('gh-'+k))}catch(e){return null}}
const data={games:read('games')||defaults.games,servers:read('servers')||defaults.servers,friends:read('friends')||defaults.friends,profile:read('profile')||defaults.profile};
let page='home';
const save=()=>Object.keys(data).forEach(k=>localStorage.setItem('gh-'+k,JSON.stringify(data[k])));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const heading=(t,s,group='GAMEHUB')=>'<header class="page-head"><div class="eyebrow">'+group+'</div><h1>'+t+'</h1><p class="muted">'+s+'</p></header>';
const btn=(label,action,cls='btn')=>'<button type="button" class="'+cls+'" data-action="'+action+'">'+label+'</button>';
function gameCards(){return data.games.map((g,i)=>'<article class="card game-card"><div class="game-icon">'+esc(g.icon)+'</div><h3>'+esc(g.name)+'</h3><p class="muted">'+esc(g.meta)+'</p>'+btn(g.favorite?'★ Favorited':'☆ Add favorite','fav-game:'+i,'btn secondary')+'</article>').join('')}
function serverCards(){return data.servers.map(s=>'<article class="card server-card"><div class="row"><h3>🖥️ '+esc(s.name)+'</h3><span class="pill">'+(s.favorite?'★ Favorite':'Saved')+'</span></div><p class="muted">'+esc(s.edition)+' · '+esc(s.version)+'</p><div class="list-item"><span>🌐</span><div class="grow"><strong>Server address</strong><small>'+esc(s.address)+'</small></div>'+btn('Copy','copy:'+s.id,'btn secondary')+'</div><div class="row" style="margin-top:14px">'+btn('Edit','edit-server:'+s.id,'btn secondary')+btn('Remove','remove-server:'+s.id,'btn ghost')+'</div></article>').join('')}
function home(){app.innerHTML=heading('Welcome back, '+esc(data.profile.name)+' 👋','Your games, servers, and gaming friends — all in one place.')+'<section class="hero"><div class="eyebrow">YOUR GAMING SPACE</div><h2>Ready for your next adventure?</h2><p>Keep your favorite games organized and your Minecraft server details close at hand.</p><div class="hero-actions">'+btn('🖥️ Manage servers','go:servers')+btn('🎮 My games','go:games','btn secondary')+'</div></section><div class="stat-grid"><div class="stat"><span class="stat-icon">🎮</span><div class="stat-label">Games in library</div><div class="stat-value">'+data.games.length+'</div></div><div class="stat"><span class="stat-icon">🖥️</span><div class="stat-label">Saved servers</div><div class="stat-value">'+data.servers.length+'</div></div><div class="stat"><span class="stat-icon">👥</span><div class="stat-label">Friends added</div><div class="stat-value">'+data.friends.length+'</div></div></div><div class="section-title">My Games '+btn('View all →','go:games','btn secondary')+'</div><div class="grid">'+gameCards()+'</div><div class="section-title">Saved Minecraft Servers</div><div class="grid">'+(data.servers.length?serverCards():'<div class="empty">No saved servers yet. Add one from My Servers.</div>')+'</div><p class="footer-note">Live status and hosting controls require a supported server service connection.</p>'}
function games(){app.innerHTML=heading('My Games','Organize your games and projects.')+'<input id="gameSearch" class="search" placeholder="Search your games..."><div class="grid" id="gameGrid">'+gameCards()+'</div><section class="card" style="margin-top:16px"><h3>＋ Add a game</h3><form id="gameForm"><label class="field-label" for="gameName">Game name</label><input class="field" id="gameName" required placeholder="e.g. Fortnite"><label class="field-label" for="gameMeta">Platform or notes</label><input class="field" id="gameMeta" placeholder="PC, console, VR..."><button class="btn" style="margin-top:14px">Add game</button></form></section>'}
const hostingProviders=[
{id:'aternos',name:'Aternos',icon:'🟦',description:'Free Minecraft server hosting',url:'https://aternos.org/'},
{id:'minehut',name:'Minehut',icon:'🟩',description:'Minecraft server hosting and community',url:'https://minehut.com/'},
{id:'falix',name:'FalixNodes',icon:'🟪',description:'Minecraft and game server hosting',url:'https://falixnodes.net/'},
{id:'serverpro',name:'Server.pro',icon:'🟧',description:'Minecraft server hosting',url:'https://server.pro/'}
];
function hostCards(){return hostingProviders.map(h=>'<article class="card"><div class="feature-icon">'+h.icon+'</div><h3>'+esc(h.name)+'</h3><p class="muted">'+esc(h.description)+'</p>'+btn('Select provider','go:hostselector')+' <a class="btn secondary" href="'+h.url+'" target="_blank" rel="noopener noreferrer">Open official site ↗</a></article>').join('')}
function openHost(id){const h=hostingProviders.find(x=>x.id===id);const panel=document.getElementById('hostEmbed');if(!h||!panel)return;panel.innerHTML='<div class="row"><div><h3 style="margin:0">🌐 '+esc(h.name)+'</h3><p class="muted">Hosting dashboard preview</p></div><div style="margin-left:auto">'+btn('Open in new tab ↗','host-external:'+h.id,'btn secondary')+' '+btn('Close','close-host','btn ghost')+'</div></div><div class="notice" style="margin:12px 0">If the host blocks embedded pages, the preview may stay blank. Use “Open in new tab” to access its official dashboard.</div><iframe title="'+esc(h.name)+' hosting website" src="'+h.url+'" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" style="display:block;width:100%;height:min(70vh,720px);min-height:420px;border:1px solid var(--border,#26364d);border-radius:12px;background:#fff"></iframe>';panel.scrollIntoView({behavior:'smooth',block:'start'})}
function servers(){app.innerHTML=heading('Manage Servers','Choose a Minecraft hosting provider, or manage the server addresses you have saved.','ACCOUNT & SERVER')+'<div class="hero"><h2>🧱 Your Minecraft servers</h2><p>Choose a hosting provider below to view its website inside GameHub, or save Java and Bedrock server addresses here.</p>'+btn('Server Finder','go:finder','btn secondary')+' '+btn('Server Settings','go:settings','btn secondary')+'</div><div class="section-title">Choose a Minecraft server host</div><p class="muted">Select a host to open its website in the embedded preview. Some providers block embedding; if that happens, use the new-tab option.</p><div class="grid">'+hostCards()+'</div><section id="hostEmbed" class="card" style="display:block;margin-top:16px"><div class="empty">Select a hosting provider above to open its website here.</div></section><div class="section-title">Your saved servers <small>'+data.servers.length+' saved</small></div><div class="grid">'+(data.servers.length?serverCards():'<div class="empty">No saved servers yet. Add one below.</div>')+'</div><section class="card" style="margin-top:17px"><h3>＋ Add a server</h3><form id="serverForm"><div class="form-row"><div><label class="field-label" for="serverName">Server name</label><input class="field" id="serverName" required placeholder="My Minecraft server"></div><div><label class="field-label" for="serverAddress">Server address / IP</label><input class="field" id="serverAddress" required placeholder="play.example.net"></div></div><div class="form-row"><div><label class="field-label" for="serverVersion">Minecraft version</label><input class="field" id="serverVersion" placeholder="1.21.x"></div><div><label class="field-label" for="serverEdition">Edition</label><select class="field" id="serverEdition"><option>Java</option><option>Bedrock</option><option>Java + Bedrock</option></select></div></div><label class="checkbox-line"><input type="checkbox" id="serverFavorite"> Add to favorites</label><button class="btn">Save server</button></form></section>'}
function account(){app.innerHTML=heading('Account','Set up your GameHub profile on this device.','ACCOUNT & SERVER')+'<div class="grid"><section class="card"><div class="feature-icon">👤</div><h3>Player profile</h3><form id="profileForm"><label class="field-label" for="profileName">Display name</label><input class="field" id="profileName" maxlength="30" required value="'+esc(data.profile.name)+'"><label class="field-label" for="profileStatus">Gaming status</label><select class="field" id="profileStatus">'+['Ready to play','In a game','Building','Away'].map(s=>'<option '+(data.profile.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select><label class="field-label" for="profileBio">About me</label><input class="field" id="profileBio" maxlength="120" value="'+esc(data.profile.bio)+'"><button class="btn" style="margin-top:14px">Save profile</button></form></section><section class="card"><div class="feature-icon">🔐</div><h3>Account & privacy</h3><p class="muted">This preview saves data in this browser on this device. Online accounts and cross-device sync are not connected yet.</p><div class="notice">When real accounts are added, we will use secure authentication instead of saving passwords in the app.</div></section></div>'}
function finder(){app.innerHTML=heading('Server Finder','Search saved server details or add a server you know.','ACCOUNT & SERVER')+'<input id="serverSearch" class="search" placeholder="Search saved servers..."><div class="grid" id="serverGrid">'+(data.servers.length?serverCards():'<div class="empty">No saved servers yet.</div>')+'</div><div class="notice">A public server directory and real online checks are not connected yet.</div>'}
function settings(){app.innerHTML=heading('Server Settings','Manage your saved server list.','ACCOUNT & SERVER')+'<div class="grid"><section class="card"><div class="feature-icon">⭐</div><h3>Favorites</h3><p class="muted">'+data.servers.filter(s=>s.favorite).length+' favorite server(s)</p>'+btn('Manage servers','go:servers')+'</section><section class="card"><div class="feature-icon">💾</div><h3>Backup</h3><p class="muted">Download your saved server list or restore the example list.</p>'+btn('Export server backup','export')+'<div style="margin-top:10px">'+btn('Restore sample servers','reset','btn secondary')+'</div></section></div><div class="notice">Starting/stopping servers, console, plugins, and live player counts require a supported hosting API.</div>'}
function friends(){app.innerHTML=heading('Friends','Create a local list of your gaming friends.')+'<section class="card"><h3>＋ Add a friend</h3><form id="friendForm"><label class="field-label" for="friendName">Gaming name</label><input class="field" id="friendName" maxlength="40" required placeholder="Friend username"><button class="btn" style="margin-top:12px">Add friend</button></form></section><div class="section-title">Your friends</div><section class="card">'+(data.friends.length?data.friends.map((f,i)=>'<div class="list-item"><div class="mini-avatar">👤</div><div class="grow"><strong>'+esc(f)+'</strong><small>Online presence not connected</small></div>'+btn('Remove','remove-friend:'+i,'btn ghost')+'</div>').join(''):'<div class="empty">Your friends list is empty.</div>')+'</section>'}
function community(){app.innerHTML=heading('Community','Connect your gaming groups and community links.')+'<div class="grid"><section class="card"><div class="feature-icon">💬</div><h3>Discord community</h3><form id="discordForm"><label class="field-label" for="discordUrl">Discord invite URL</label><input class="field" type="url" id="discordUrl" placeholder="https://discord.gg/yourinvite"><button class="btn" style="margin-top:12px">Save invite</button></form>'+btn('Open saved invite','open-discord','btn secondary')+'</section><section class="card"><div class="feature-icon">📣</div><h3>Announcements</h3><p class="muted">A future home for GameHub updates, events, and server news.</p><span class="pill">Coming next</span></section><section class="card"><div class="feature-icon">🛡️</div><h3>Stay safe</h3><p class="muted">Never share your password or private recovery codes in public chats.</p></section></div>'}
function profile(){app.innerHTML=heading('Player Profile','Your gaming identity on GameHub.')+'<section class="card" style="max-width:650px"><div class="row"><div class="mini-avatar" style="width:58px;height:58px;font-size:24px">🎮</div><div style="flex:1"><h2 style="margin:0 0 5px">'+esc(data.profile.name)+'</h2><span class="pill">'+esc(data.profile.status)+'</span></div>'+btn('Edit profile','go:account','btn secondary')+'</div><p class="muted" style="margin-top:20px">'+esc(data.profile.bio||'No bio yet.')+'</p><div class="stat-grid" style="margin-top:22px"><div class="stat"><div class="stat-label">Games</div><div class="stat-value">'+data.games.length+'</div></div><div class="stat"><div class="stat-label">Servers</div><div class="stat-value">'+data.servers.length+'</div></div><div class="stat"><div class="stat-label">Friends</div><div class="stat-value">'+data.friends.length+'</div></div></div></section>'}
function publicServers(){const drafts=read('listingDrafts')||[];app.innerHTML=heading('Public Server Browser','Discover community servers and publish yours for other players to find.','COMMUNITY')+'<div class="hero"><h2>🌍 Find your next server</h2><p>Browse public Minecraft servers once the shared directory is connected. You can prepare a listing now; drafts saved here are only on this device and are not visible to other players yet.</p>'+btn('Publish a server','go:publish')+'</div><div class="section-title">Community server directory</div><section class="card"><div class="empty">The public directory is not connected yet. Once we connect a shared backend, published servers can appear here for everyone to browse.</div></section><div class="section-title">Your listing drafts <small>'+drafts.length+'</small></div><div class="grid">'+(drafts.length?drafts.map((d,i)=>'<article class="card"><div class="row"><h3>🧱 '+esc(d.name)+'</h3><span class="pill">Draft</span></div><p class="muted">'+esc(d.edition)+' · '+esc(d.version)+'</p><p>'+esc(d.description||'No description added.')+'</p><div class="list-item"><div class="grow"><strong>Server address</strong><small>'+esc(d.address)+'</small></div>'+btn('Copy address','copy-draft:'+i,'btn secondary')+'</div>'+btn('Edit listing','edit-draft:'+i,'btn secondary')+'</article>').join(''):'<div class="empty">No drafts yet. Use Publish a server to prepare your listing.</div>')+'</div><div class="notice" style="margin-top:16px">Important: a listing in GameHub does not host the Minecraft server itself. Players need a reachable server address, and real public publishing requires the shared directory backend.</div>'}
function publishServer(){const drafts=read('listingDrafts')||[];app.innerHTML=heading('Publish a Server','Prepare a public listing so other players can discover your Minecraft server.','COMMUNITY')+'<section class="card"><div class="notice">Sign in to publish this listing to the shared GameHub directory. If you are not signed in, your listing will be saved as a local draft.</div><form id="publishForm" style="margin-top:16px"><label class="field-label" for="pubName">Server name</label><input class="field" id="pubName" maxlength="50" required placeholder="e.g. WhiteBoardSMP"><label class="field-label" for="pubAddress">Public server address</label><input class="field" id="pubAddress" maxlength="180" required placeholder="play.example.net or IP:port"><div class="form-row"><div><label class="field-label" for="pubEdition">Edition</label><select class="field" id="pubEdition"><option>Java</option><option>Bedrock</option><option>Java + Bedrock</option></select></div><div><label class="field-label" for="pubVersion">Minecraft version</label><input class="field" id="pubVersion" maxlength="30" placeholder="1.21.x"></div></div><label class="field-label" for="pubDescription">Description</label><textarea class="field" id="pubDescription" maxlength="400" rows="3" placeholder="What makes your server fun?"></textarea><label class="field-label" for="pubTags">Tags (comma separated)</label><input class="field" id="pubTags" maxlength="120" placeholder="Survival, SMP, Crossplay"><label class="checkbox-line"><input type="checkbox" id="pubConfirm" required> I have permission to share this server address publicly.</label><button class="btn">Publish server listing</button> '+btn('Cancel','go:public','btn secondary')+'</form></section><div class="section-title">What happens next?</div><div class="grid"><article class="card"><h3>1. Save your draft</h3><p class="muted">Review the name, address, edition, and description.</p></article><article class="card"><h3>2. Connect the public directory</h3><p class="muted">A shared backend is needed so other players can see listings from their own devices.</p></article><article class="card"><h3>3. Publish and share</h3><p class="muted">After backend setup, listings can be reviewed, browsed, and used to copy the server address.</p></article></div>'}
const modCatalog=[
{id:'geyser',name:'GeyserMC',kind:'Plugin / bridge',platform:'Java server + Bedrock clients',description:'Lets Bedrock players join compatible Java Edition servers.',url:'https://geysermc.org/'},
{id:'floodgate',name:'Floodgate',kind:'Plugin',platform:'Paper / compatible servers',description:'Allows Bedrock players to authenticate without a Java account when configured with Geyser.',url:'https://geysermc.org/'},
{id:'iris',name:'Iris Shaders',kind:'Client mod',platform:'Fabric / Quilt',description:'Shader loader for compatible Minecraft Java clients.',url:'https://irisshaders.dev/'},
{id:'sodium',name:'Sodium',kind:'Client mod',platform:'Fabric / compatible versions',description:'Rendering performance optimization.',url:'https://modrinth.com/mod/sodium'},
{id:'lithium',name:'Lithium',kind:'Optimization mod',platform:'Fabric / compatible versions',description:'Game logic optimizations.',url:'https://modrinth.com/mod/lithium'},
{id:'fabric-api',name:'Fabric API',kind:'Library',platform:'Fabric',description:'Required library for many Fabric mods.',url:'https://modrinth.com/mod/fabric-api'},
{id:'create',name:'Create',kind:'Content mod',platform:'Supported Java mod loaders',description:'Mechanical engineering, automation, and moving contraptions.',url:'https://modrinth.com/mod/create-fabric'},
{id:'voicechat',name:'Simple Voice Chat',kind:'Mod / plugin',platform:'Compatible Java clients and servers',description:'Proximity voice chat; client and server setup may both be required.',url:'https://modrinth.com/plugin/simple-voice-chat'},
{id:'viaversion',name:'ViaVersion',kind:'Server plugin',platform:'Paper / compatible servers',description:'Allows supported newer clients to connect to older server versions.',url:'https://viaversion.com/'},
{id:'shaders',name:'Shader packs (Iris compatible)',kind:'Shader pack',platform:'Java client with compatible shader loader',description:'Visual shader packs are separate from mods and need a compatible loader.',url:'https://modrinth.com/shaders'}
];
function readModPacks(){return read('modPacks')||[]}
function modCategory(m){if(m.id==='geyser'||m.id==='floodgate')return 'Crossplay';if(m.id==='iris'||m.id==='shaders')return 'Shaders';if(m.id==='sodium'||m.id==='lithium')return 'Performance';if(m.id==='fabric-api')return 'Libraries';if(m.id==='create')return 'Content';if(m.id==='voicechat')return 'Voice Chat';if(m.id==='viaversion')return 'Server Plugins';return m.category||'Other'}
function allModItems(){return [...modCatalog,...(read('customMods')||[]).map(m=>({...m,platform:m.platform||'Custom entry',description:m.description||m.kind||'User-added item',category:m.category||'Custom'}))]}
function modCard(m,selected=[]){return '<label class="card mod-option" data-category="'+esc(modCategory(m).toLowerCase())+'" data-search="'+esc((m.name+' '+m.kind+' '+m.description+' '+m.platform+' '+modCategory(m)).toLowerCase())+'"><span class="row"><input type="checkbox" name="modItem" value="'+esc(m.id)+'" '+(selected.includes(m.id)?'checked':'')+'><strong>'+esc(m.name)+'</strong></span><span class="pill">'+esc(modCategory(m))+'</span><p class="muted">'+esc(m.platform||'Custom entry')+'</p><small>'+esc(m.description||m.kind||'Custom item')+'</small>'+(m.url&&/^https:\/\//i.test(m.url)?'<a class="btn secondary" href="'+esc(m.url)+'" target="_blank" rel="noopener noreferrer">Project page ↗</a>':'')+'</label>'}
function modsPage(){const packs=readModPacks();app.innerHTML=heading('Mods & Modpacks','Build a custom Minecraft setup, organize it by category, and manage your saved packs.','GAMEHUB')+'<div class="hero"><h2>🧩 Custom Mod Selector</h2><p>Browse crossplay plugins, performance mods, shader packs, libraries, and custom entries. Save your pack locally or export its JSON manifest.</p>'+btn('Create a modpack','go:modbuilder')+' '+btn('Full mod catalog','go:modcatalog','btn secondary')+' '+btn('Publish modpacks','go:publishmods','btn secondary')+'</div><div class="section-title">Browse by category</div><div class="feature-shortcuts">'+['Crossplay','Shaders','Performance','Libraries','Content','Voice Chat','Server Plugins','Custom'].map(c=>btn(c,'filter-mods:'+c,'btn secondary')).join(' ')+'</div><div class="section-title">Starter catalog</div><div class="grid">'+modCatalog.slice(0,6).map(m=>'<article class="card mod-card"><div class="row"><h3>'+esc(m.name)+'</h3><span class="pill">'+esc(modCategory(m))+'</span></div><p class="muted">'+esc(m.platform)+'</p><p>'+esc(m.description)+'</p><a class="btn secondary" href="'+m.url+'" target="_blank" rel="noopener noreferrer">Official project ↗</a></article>').join('')+'</div><div class="section-title">Your modpacks <small>'+packs.length+' saved</small></div><div class="grid">'+(packs.length?packs.map((p,i)=>'<article class="card mod-card"><div class="row"><h3>🧩 '+esc(p.name)+'</h3><span class="pill">Draft</span></div><p class="muted">'+esc(p.version||'Any version')+' · '+esc(p.loader||'Unspecified loader')+'</p><p>'+esc(p.description||'No description yet.')+'</p><p class="muted">'+(Array.isArray(p.items)?p.items.length:0)+' selected item(s): '+esc((p.items||[]).map(id=>allModItems().find(m=>m.id===id)?.name||id).join(', '))+'</p>'+btn('Edit pack','edit-modpack:'+i,'btn secondary')+' '+btn('Export JSON','export-modpack:'+i,'btn secondary')+'</article>').join(''):'<div class="empty">No modpacks yet. Create one to get started.</div>')+'</div><div class="notice">GameHub organizes mod selections and creates JSON manifests; it does not create .jar files or install mods into Minecraft automatically. Public publishing becomes available after Supabase is connected.</div>'}
function modCatalogPage(){app.innerHTML=heading('Mod Catalog','Search and filter the full starter catalog and your own custom entries.','MOD TOOLS')+'<input id="modSearch" class="search" placeholder="Search mods, plugins, shaders, or libraries..." autocomplete="off"><div class="form-row"><div><label class="field-label" for="modCategoryFilter">Category</label><select class="field" id="modCategoryFilter"><option value="all">All categories</option>'+['Crossplay','Shaders','Performance','Libraries','Content','Voice Chat','Server Plugins','Custom','Other'].map(c=>'<option value="'+c.toLowerCase()+'">'+c+'</option>').join('')+'</select></div><div><label class="field-label" for="modTypeFilter">Type</label><select class="field" id="modTypeFilter"><option value="all">All types</option>'+[...new Set(allModItems().map(m=>m.kind||'Custom item'))].map(c=>'<option value="'+esc(c.toLowerCase())+'">'+esc(c)+'</option>').join('')+'</select></div></div><div id="modCatalogGrid" class="grid">'+allModItems().map(m=>'<article class="card mod-card" data-category="'+esc(modCategory(m).toLowerCase())+'" data-type="'+esc((m.kind||'custom item').toLowerCase())+'" data-search="'+esc((m.name+' '+m.kind+' '+m.description+' '+m.platform+' '+modCategory(m)).toLowerCase())+'"><div class="row"><h3>'+esc(m.name)+'</h3><span class="pill">'+esc(modCategory(m))+'</span></div><p class="muted">'+esc(m.platform||'Custom entry')+'</p><p>'+esc(m.description||m.kind||'Custom item')+'</p>'+(m.url&&/^https:\/\//i.test(m.url)?'<a class="btn secondary" href="'+esc(m.url)+'" target="_blank" rel="noopener noreferrer">Project page ↗</a>':'<span class="pill">Custom item</span>')+'</article>').join('')+'</div><div class="notice">Always verify the Minecraft version, loader, dependencies, and project download source before installing.</div>'}
function modBuilder(editIndex=null){const packs=readModPacks();const old=editIndex!==null?packs[editIndex]:null;const selected=old?.items||['geyser','iris','sodium'];const items=allModItems();app.innerHTML=heading(old?'Edit Modpack':'Create a Modpack','Build a pack with categories, a target Minecraft version, and custom entries.','MOD TOOLS')+'<section class="card"><form id="modPackForm" data-edit-index="'+(editIndex===null?'':editIndex)+'"><label class="field-label" for="packName">Modpack name</label><input class="field" id="packName" maxlength="60" required value="'+esc(old?.name||'')+'" placeholder="e.g. WhiteBoard Crossplay Pack"><div class="form-row"><div><label class="field-label" for="packVersion">Minecraft version</label><input class="field" id="packVersion" maxlength="30" required value="'+esc(old?.version||'1.21.x')+'" placeholder="1.21.x"></div><div><label class="field-label" for="packLoader">Loader / server type</label><select class="field" id="packLoader">'+['Paper / Spigot','Fabric','Forge','NeoForge','Quilt','Vanilla / datapacks','Mixed / server plugins'].map(x=>'<option '+((old?.loader||'Paper / Spigot')===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div></div><label class="field-label" for="packDescription">Description</label><textarea class="field" id="packDescription" maxlength="500" rows="3" placeholder="Describe what this pack adds...">'+esc(old?.description||'')+'</textarea><div class="section-title">Find items by category</div><input id="builderModSearch" class="search" placeholder="Search catalog..."><div class="category-pills">'+['All','Crossplay','Shaders','Performance','Libraries','Content','Voice Chat','Server Plugins','Custom','Other'].map((c,i)=>btn(c,'builder-category:'+c.toLowerCase(),i===0?'btn':'btn secondary')).join(' ')+'</div><div id="builderModGrid" class="grid">'+items.map(m=>modCard(m,selected)).join('')+'</div><div class="section-title">Add a custom item</div><div class="form-row"><div><label class="field-label" for="customModName">Name</label><input class="field" id="customModName" maxlength="60" placeholder="Your mod / plugin / shader"></div><div><label class="field-label" for="customModUrl">Project URL (optional)</label><input class="field" type="url" id="customModUrl" placeholder="https://..."></div></div><label class="field-label" for="customModKind">Category / type / notes</label><select class="field" id="customModKind"><option>Custom</option><option>Crossplay</option><option>Shader pack</option><option>Performance</option><option>Library</option><option>Content mod</option><option>Voice Chat</option><option>Server Plugin</option><option>Datapack</option></select><button type="button" class="btn secondary" data-action="add-custom-mod">Add custom item to selection</button><div id="customModStatus" class="muted" style="margin-top:8px"></div><div class="row" style="margin-top:18px;flex-wrap:wrap">'+btn('Save draft','save-modpack')+' '+btn('Cancel','go:mods','btn secondary')+'</div></form></section><div class="notice" style="margin-top:14px">Saving a draft keeps it on this device. JSON export is a manifest, not an installable modpack archive. Shared publishing requires the separate GameHub Supabase project.</div>'}
function publishModpacks(){const packs=readModPacks();app.innerHTML=heading('Publish Modpacks','Review your modpacks before sharing them with the GameHub community.','COMMUNITY')+'<div class="hero"><h2>📦 Share your setup</h2><p>Sign in to publish a saved modpack to the shared community library.</p>'+btn('Create modpack','go:modbuilder')+' '+btn('Browse catalog','go:modcatalog','btn secondary')+'</div><div class="grid">'+(packs.length?packs.map((p,i)=>'<article class="card"><h3>'+esc(p.name)+'</h3><p class="muted">'+esc(p.version||'Any version')+' · '+esc(p.loader||'Unspecified')+'</p><p>'+esc(p.description||'No description.')+'</p><span class="pill">Local draft</span><div style="margin-top:12px">'+btn('Edit','edit-modpack:'+i,'btn secondary')+' '+btn('Export JSON','export-modpack:'+i,'btn secondary')+' '+btn('Publish','publish-modpack:'+i,'btn')+'</div></article>').join(''):'<div class="empty">Create a modpack first, then it will appear here.</div>')+'</div><div class="notice">No modpack is public yet. This page will not claim a pack was published until the shared database is actually connected.</div>'}
function hostSelector(){app.innerHTML=heading('Server Host Selector','Choose a hosting provider and open its official dashboard.','ACCOUNT & SERVER')+'<div class="hero"><h2>🖥️ Choose where to host</h2><p>Select a provider to see its details and launch the official website. External opening is more reliable than embedding hosts that block previews.</p></div><div class="grid">'+hostingProviders.map(h=>'<article class="card mod-card"><div class="feature-icon">'+h.icon+'</div><h3>'+esc(h.name)+'</h3><p class="muted">'+esc(h.description)+'</p><div class="host-actions">'+btn('Select provider','select-host:'+h.id)+' <a class="btn secondary" href="'+h.url+'" target="_blank" rel="noopener noreferrer">Open official site ↗</a></div><div id="hostDetail-'+h.id+'" class="muted" style="margin-top:10px"></div></article>').join('')+'</div><div class="notice">GameHub cannot sign in to or control a host dashboard inside this page. Use the official provider website; host APIs require separate integration.</div>'}
function gameTools(){app.innerHTML=heading('Gaming Tools','Quick helpers for your gaming setup.','GAMEHUB TOOLS')+'<div class="grid"><section class="card"><div class="feature-icon">📋</div><h3>Server address checker</h3><p class="muted">Validate the shape of an address before saving it.</p><input id="addressCheck" class="field" placeholder="play.example.net:25565"><div style="margin-top:10px">'+btn('Check address','check-address')+'</div><p id="addressCheckResult" class="muted"></p></section><section class="card"><div class="feature-icon">🧾</div><h3>Backup & export</h3><p class="muted">Export your saved GameHub data to a JSON file.</p>'+btn('Export all local data','export-all')+'</section><section class="card"><div class="feature-icon">🧩</div><h3>Modpack builder</h3><p class="muted">Choose mods, plugins, shaders, and categories.</p>'+btn('Open modpack builder','go:modbuilder')+'</section></div>'}

function authPage(){app.innerHTML=heading('GameHub Account','Sign in to publish modpacks and server listings across devices.','ACCOUNT')+'<section class="card"><h2>🔐 Community account</h2><p class="muted">Local saves stay on this device. Sign in to publish shared content.</p><div id="authStatus" class="notice">Checking account…</div><form id="authForm" style="margin-top:16px"><label class="field-label" for="authEmail">Email</label><input class="field" id="authEmail" type="email" required autocomplete="email" placeholder="you@example.com"><label class="field-label" for="authPassword">Password</label><input class="field" id="authPassword" type="password" required minlength="6" autocomplete="current-password" placeholder="At least 6 characters"><div class="row" style="margin-top:14px;flex-wrap:wrap"><button class="btn" type="submit" name="authMode" value="signin">Sign in</button><button class="btn secondary" type="submit" name="authMode" value="signup">Create account</button></div></form><div style="margin-top:12px">'+btn('Sign out','auth-signout','btn ghost')+'</div></section>';if(!window.ghSupabase){document.getElementById('authStatus').textContent='Supabase client unavailable. Check internet and reload.';return}window.ghSupabase.auth.getSession().then(({data,error})=>{const el=document.getElementById('authStatus');if(el)el.textContent=error?'Account check failed: '+error.message:data.session?'Signed in as '+data.session.user.email:'Not signed in.'})}
async function communityModpacks(){app.innerHTML=heading('Community Modpacks','Browse modpacks published by GameHub players.','COMMUNITY')+'<div class="hero"><h2>📦 Shared modpack library</h2><p>Verify supported versions and dependencies before installing.</p>'+btn('Build a pack','go:modbuilder')+' '+btn('Publish a pack','go:publishmods','btn secondary')+'</div><div id="communityModpackResults" class="grid"><div class="empty">Loading published modpacks…</div></div>';const el=document.getElementById('communityModpackResults');if(!window.ghSupabase){el.innerHTML='<div class="empty">Database connection unavailable.</div>';return}const {data:rows,error}=await window.ghSupabase.from('gamehub_modpacks').select('id,name,description,minecraft_version,loader,items,tags,created_at').eq('published',true).order('created_at',{ascending:false}).limit(60);if(!document.getElementById('communityModpackResults'))return;if(error){el.innerHTML='<div class="empty">Could not load packs: '+esc(error.message)+'</div>';return}window.ghCommunityPacks=rows||[];el.innerHTML=rows&&rows.length?rows.map(p=>'<article class="card mod-card"><div class="row"><h3>🧩 '+esc(p.name)+'</h3><span class="pill">Published</span></div><p class="muted">'+esc(p.minecraft_version)+' · '+esc(p.loader)+'</p><p>'+esc(p.description||'No description.')+'</p><p class="muted">'+(Array.isArray(p.items)?p.items.length:0)+' selected items</p>'+btn('Export manifest','export-community-pack:'+p.id,'btn secondary')+'</article>').join(''):'<div class="empty">No public modpacks yet. Publish the first one.</div>'}
function modChecklistPage(){const packs=readModPacks();app.innerHTML=heading('Modpack Checklist','Review dependencies and setup warnings before playing.','MOD TOOLS')+'<section class="card"><label class="field-label" for="checkPackSelect">Choose a saved pack</label><select id="checkPackSelect" class="field"><option value="">Select a pack…</option>'+packs.map((p,i)=>'<option value="'+i+'">'+esc(p.name)+'</option>').join('')+'</select><div id="checklistOutput" class="muted" style="margin-top:14px">Choose a pack to inspect it.</div></section><div class="notice" style="margin-top:14px">This is a rule-based checklist, not a guarantee. Verify each project&#39;s supported Minecraft version and loader.</div>'}
function compatibilityPage(){app.innerHTML=heading('Compatibility Checker','Quickly review crossplay and shader setup requirements.','MOD TOOLS')+'<section class="card"><label class="field-label" for="compatVersion">Minecraft version</label><input id="compatVersion" class="field" placeholder="1.21.4"><label class="field-label" for="compatLoader">Server software / loader</label><select id="compatLoader" class="field"><option>Paper / Spigot</option><option>Fabric</option><option>Forge</option><option>NeoForge</option><option>Quilt</option><option>Vanilla</option></select><label class="checkbox-line"><input type="checkbox" id="compatBedrock"> Bedrock players need to join Java</label><label class="checkbox-line"><input type="checkbox" id="compatShaders"> I want shaders on a Java client</label><div style="margin-top:14px">'+btn('Check setup','run-compatibility')+'</div><div id="compatResult" style="margin-top:14px"></div></section>'}
function favoritesPage(){const fg=data.games.filter(g=>g.favorite),fs=data.servers.filter(s=>s.favorite);app.innerHTML=heading('Favorites','Your starred games and saved servers.','GAMEHUB')+'<div class="section-title">Favorite games</div><div class="grid">'+(fg.length?fg.map(g=>'<article class="card"><h3>'+esc(g.icon||'🎮')+' '+esc(g.name)+'</h3><p class="muted">'+esc(g.meta||'')+'</p></article>').join(''):'<div class="empty">No favorite games yet.</div>')+'</div><div class="section-title">Favorite servers</div><div class="grid">'+(fs.length?fs.map(s=>'<article class="card"><h3>🖥️ '+esc(s.name)+'</h3><p class="muted">'+esc(s.address)+'</p>'+btn('Copy address','copy:'+s.id,'btn secondary')+'</article>').join(''):'<div class="empty">No favorite servers yet.</div>')+'</div>'}

const render={home,games,servers,account,finder,settings,friends,community,profile,public:publicServers,publish:publishServer,mods:modsPage,modbuilder:()=>modBuilder(),modcatalog:modCatalogPage,publishmods:publishModpacks,hostselector:hostSelector,tools:gameTools,auth:authPage,communitymods:communityModpacks,modchecklist:modChecklistPage,compatibility:compatibilityPage,favorites:favoritesPage};
function go(p){if(!render[p])return;page=p;document.querySelectorAll('.nav[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render[p]();const count=document.getElementById('serverCount');if(count)count.textContent=data.servers.length;window.scrollTo(0,0)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){go(b.dataset.page);return}const a=b.dataset.action;if(!a)return;if(a.startsWith('go:'))return go(a.slice(3));if(a.startsWith('filter-mods:')){go('modcatalog');const v=a.slice(12).toLowerCase();const f=document.getElementById('modCategoryFilter');if(f)f.value=v;filterModCatalog();return}if(a.startsWith('builder-category:')){const v=a.slice(17);document.querySelectorAll('[data-action^="builder-category:"]').forEach(x=>{x.classList.toggle('btn',x.dataset.action==='builder-category:'+v);x.classList.toggle('secondary',x.dataset.action!=='builder-category:'+v)});document.querySelectorAll('#builderModGrid .mod-option').forEach(x=>x.style.display=v==='all'||x.dataset.category===v?'':'none');return}if(a.startsWith('select-host:')){const id=a.slice(12);const h=hostingProviders.find(x=>x.id===id);const p=document.getElementById('hostDetail-'+id);if(p&&h)p.innerHTML='Selected '+esc(h.name)+'. Use “Open official site” to continue to its dashboard.';return}if(a==='check-address'){const v=(document.getElementById('addressCheck')?.value||'').trim();const out=document.getElementById('addressCheckResult');if(out)out.textContent=!v?'Enter an address first.':(/^[a-z0-9.-]+(?::[0-9]{1,5})?$/i.test(v)?'Address format looks valid. This does not confirm that the server is online.':'Check the hostname and optional port (example: play.example.net:25565).');return}if(a==='export-all'){const payload={games:data.games,servers:data.servers,friends:data.friends,profile:data.profile,modpacks:readModPacks(),listingDrafts:read('listingDrafts')||[]};const u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download='gamehub-backup.json';link.click();URL.revokeObjectURL(u);return}if(a==='auth-signout'){if(window.ghSupabase){const {error}=await window.ghSupabase.auth.signOut();if(error)alert(error.message);else{alert('Signed out.');go('auth')}}return}if(a==='run-compatibility'){const v=document.getElementById('compatVersion').value.trim()||'not specified';const loader=document.getElementById('compatLoader').value;const bed=document.getElementById('compatBedrock').checked;const shaders=document.getElementById('compatShaders').checked;let notes=['Target version: '+v+'. Verify that every plugin/mod supports this exact version.'];if(bed){if(loader==='Paper / Spigot')notes.push('Crossplay: install GeyserMC on the server; Floodgate is optional for a configured Bedrock-friendly authentication flow. Confirm UDP port access for Bedrock.');else notes.push('Crossplay warning: Geyser is usually easiest on Paper/Spigot or as a supported proxy plugin. Check the official Geyser compatibility guide for this server software.')}if(shaders)notes.push('Shaders: use a compatible Java client setup such as Iris with a supported shader pack; shader support is client-side and does not make Bedrock shaders work.');if(loader==='Vanilla'&&(bed||shaders))notes.push('Vanilla does not load ordinary server plugins; use compatible server software or client-side tools where applicable.');document.getElementById('compatResult').innerHTML='<div class="notice"><strong>Setup checklist</strong><ul>'+notes.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul></div>';return}if(a.startsWith('copy-public-server:')){const id=a.slice(19);const rows=await window.ghSupabase.from('gamehub_server_listings').select('address').eq('id',id).limit(1);if(rows.data?.[0]){try{await navigator.clipboard.writeText(rows.data[0].address);b.textContent='Copied!'}catch{prompt('Copy server address:',rows.data[0].address)}}return}if(a.startsWith('export-community-pack:')){const p=(window.ghCommunityPacks||[]).find(x=>x.id===a.slice(22));if(!p)return;const u=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download=(p.name||'gamehub-community-pack').replace(/[^a-z0-9_-]/gi,'-')+'.json';link.click();URL.revokeObjectURL(u);return}if(a.startsWith('publish-modpack:')){const idx=Number(a.slice(16));const p=readModPacks()[idx];if(!p)return;const client=window.ghSupabase;const auth=client?await client.auth.getUser():{data:{user:null}};if(!auth.data?.user){alert('Sign in before publishing a modpack.');return go('auth')}const custom=read('customMods')||[];const manifest={...p,customItems:custom.filter(m=>(p.items||[]).includes(m.id))};const {error}=await client.from('gamehub_modpacks').insert({owner_id:auth.data.user.id,name:p.name,description:p.description||'',minecraft_version:p.version||'1.21.x',loader:p.loader||'Unspecified',items:p.items||[],manifest,tags:[],published:true});if(error)return alert('Could not publish modpack: '+error.message);alert('Modpack published to the shared GameHub library!');return go('communitymods')}if(a.startsWith('host:'))return openHost(a.slice(5));if(a.startsWith('host-external:')){const h=hostingProviders.find(x=>x.id===a.slice(14));if(h)window.open(h.url,'_blank','noopener,noreferrer');return}if(a==='close-host'){const p=document.getElementById('hostEmbed');if(p)p.innerHTML='<div class="empty">Select a hosting provider above to open its website here.</div>';return}if(a.startsWith('fav-game:')){const g=data.games[Number(a.split(':')[1])];if(g)g.favorite=!g.favorite;save();return go(page)}if(a.startsWith('remove-server:')){data.servers=data.servers.filter(s=>s.id!==Number(a.split(':')[1]));save();return go(page)}if(a.startsWith('remove-friend:')){data.friends.splice(Number(a.split(':')[1]),1);save();return go('friends')}if(a.startsWith('edit-server:')){const s=data.servers.find(s=>s.id===Number(a.split(':')[1]));if(!s)return;const n=prompt('Server name:',s.name);if(n===null)return;const addr=prompt('Server address:',s.address);if(addr===null)return;s.name=n.trim()||s.name;s.address=addr.trim()||s.address;save();return go(page)}if(a.startsWith('edit-modpack:')){const idx=Number(a.split(':')[1]);return modBuilder(idx)}if(a.startsWith('export-modpack:')){const packs=readModPacks();const p=packs[Number(a.split(':')[1])];if(!p)return;const u=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download=(p.name||'gamehub-modpack').replace(/[^a-z0-9_-]/gi,'-')+'.json';link.click();URL.revokeObjectURL(u);return}if(a==='add-custom-mod'){const f=document.getElementById('modPackForm');if(!f)return;const name=document.getElementById('customModName').value.trim();if(!name)return alert('Enter a custom item name first.');const url=document.getElementById('customModUrl').value.trim();if(url&&!/^https:\/\//i.test(url))return alert('Use an HTTPS project URL.');const kind=document.getElementById('customModKind').value.trim()||'Custom';let custom=read('customMods')||[];const id='custom-'+Date.now();custom.push({id,name,kind,url,category:kind});localStorage.setItem('gh-customMods',JSON.stringify(custom));const label=document.getElementById('customModStatus');if(label)label.textContent='Added '+name+'. Save the pack draft to keep this selection.';let hidden=document.createElement('input');hidden.type='checkbox';hidden.name='modItem';hidden.value=id;hidden.checked=true;hidden.style.display='none';f.appendChild(hidden);document.getElementById('customModName').value='';document.getElementById('customModUrl').value='';document.getElementById('customModKind').value='';return}if(a==='save-modpack'){const f=document.getElementById('modPackForm');if(!f)return;const name=document.getElementById('packName').value.trim();if(!name)return alert('Enter a modpack name.');const items=[...f.querySelectorAll('input[name="modItem"]:checked')].map(x=>x.value);const custom=read('customMods')||[];const index=f.dataset.editIndex===''?null:Number(f.dataset.editIndex);const pack={id:index===null?Date.now():(readModPacks()[index]?.id||Date.now()),name,version:document.getElementById('packVersion').value.trim(),loader:document.getElementById('packLoader').value,description:document.getElementById('packDescription').value.trim(),items,customItems:custom.filter(m=>items.includes(m.id)),status:'draft',updatedAt:new Date().toISOString()};const packs=readModPacks();if(index!==null&&packs[index])packs[index]=pack;else packs.push(pack);localStorage.setItem('gh-modPacks',JSON.stringify(packs));alert('Modpack draft saved on this device. It is not public yet; connect the shared Supabase database to publish it.');return go('mods')}if(a.startsWith('copy-draft:')){const ds=read('listingDrafts')||[];const d=ds[Number(a.split(':')[1])];if(!d)return;try{await navigator.clipboard.writeText(d.address);b.textContent='Copied!'}catch{prompt('Copy server address:',d.address)}return}if(a.startsWith('edit-draft:')){const ds=read('listingDrafts')||[];const d=ds[Number(a.split(':')[1])];if(!d)return;go('publish');setTimeout(()=>{const n=document.getElementById('pubName');if(n){n.value=d.name;document.getElementById('pubAddress').value=d.address;document.getElementById('pubEdition').value=d.edition;document.getElementById('pubVersion').value=d.version;document.getElementById('pubDescription').value=d.description;document.getElementById('pubTags').value=(d.tags||[]).join(', ') }},0);return}if(a.startsWith('copy:')){const s=data.servers.find(s=>s.id===Number(a.split(':')[1]));if(!s)return;try{await navigator.clipboard.writeText(s.address);b.textContent='Copied!'}catch{prompt('Copy server address:',s.address)}return}if(a==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(data.servers,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download='gamehub-servers.json';link.click();URL.revokeObjectURL(u);return}if(a==='reset'){if(confirm('Restore the sample servers? Your saved server list will be replaced.')){data.servers=defaults.servers.map(s=>({...s}));save();go('settings')}return}if(a==='open-discord'){const u=read('discord')||'';if(/^https:\/\//i.test(u))window.open(u,'_blank','noopener,noreferrer');else alert('Save a valid HTTPS Discord invite first.')}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='authForm'){const client=window.ghSupabase;if(!client)return alert('Database connection unavailable.');const email=document.getElementById('authEmail').value.trim();const password=document.getElementById('authPassword').value;const mode=e.submitter?.value||'signin';const result=mode==='signup'?await client.auth.signUp({email,password}):await client.auth.signInWithPassword({email,password});if(result.error)return alert(result.error.message);if(mode==='signup'&&!result.data.session)return alert('Account created. Check your email to confirm the account, then sign in.');alert(mode==='signup'?'Account created and signed in.':'Signed in successfully.');return go('auth')}if(f.id==='publishForm'){const listing={name:document.getElementById('pubName').value.trim(),address:document.getElementById('pubAddress').value.trim(),edition:document.getElementById('pubEdition').value,minecraft_version:document.getElementById('pubVersion').value.trim()||'Not specified',description:document.getElementById('pubDescription').value.trim(),tags:document.getElementById('pubTags').value.split(',').map(t=>t.trim()).filter(Boolean),published:true};const client=window.ghSupabase;const auth=client?await client.auth.getUser():{data:{user:null},error:null};if(auth.data?.user){const {error}=await client.from('gamehub_server_listings').insert({...listing,owner_id:auth.data.user.id});if(error)return alert('Could not publish listing: '+error.message);alert('Server listing published to the GameHub community!');return go('public')}const drafts=read('listingDrafts')||[];drafts.push({...listing,id:Date.now(),version:listing.minecraft_version});localStorage.setItem('gh-listingDrafts',JSON.stringify(drafts));alert('Saved as a local draft. Sign in to publish it to the shared directory.');return go('public')}if(f.id==='serverForm'){data.servers.push({id:Date.now(),name:document.getElementById('serverName').value.trim(),address:document.getElementById('serverAddress').value.trim(),version:document.getElementById('serverVersion').value.trim()||'Not specified',edition:document.getElementById('serverEdition').value,favorite:document.getElementById('serverFavorite').checked});save();return go('servers')}if(f.id==='gameForm'){const name=document.getElementById('gameName').value.trim();if(name)data.games.push({icon:'🎮',name,meta:document.getElementById('gameMeta').value.trim()||'My library'});save();return go('games')}if(f.id==='profileForm'){data.profile={name:document.getElementById('profileName').value.trim()||'Player',status:document.getElementById('profileStatus').value,bio:document.getElementById('profileBio').value.trim()};save();return go('account')}if(f.id==='friendForm'){const name=document.getElementById('friendName').value.trim();if(name&&!data.friends.some(n=>n.toLowerCase()===name.toLowerCase()))data.friends.push(name);save();return go('friends')}if(f.id==='discordForm'){const url=document.getElementById('discordUrl').value.trim();if(url&&!/^https:\/\//i.test(url))return alert('Please use an HTTPS invite URL.');localStorage.setItem('gh-discord',JSON.stringify(url));alert('Invite saved on this device.')}});
function filterModCatalog(){const q=(document.getElementById('modSearch')?.value||'').toLowerCase();const c=document.getElementById('modCategoryFilter')?.value||'all';const t=document.getElementById('modTypeFilter')?.value||'all';document.querySelectorAll('#modCatalogGrid .mod-card').forEach(x=>x.style.display=(x.dataset.search||'').includes(q)&&(c==='all'||x.dataset.category===c)&&(t==='all'||x.dataset.type===t)?'':'none')}
document.addEventListener('change',e=>{if(['modCategoryFilter','modTypeFilter'].includes(e.target.id))filterModCatalog()});
document.addEventListener('change',e=>{if(e.target.id==='checkPackSelect'){const p=readModPacks()[Number(e.target.value)];const out=document.getElementById('checklistOutput');if(!out)return;if(!p){out.textContent='Choose a pack to inspect it.';return}const items=(p.items||[]).map(id=>allModItems().find(m=>m.id===id)).filter(Boolean);const warnings=[];if(!p.version)warnings.push('Choose a specific Minecraft version.');if(/Fabric|Forge|NeoForge|Quilt/i.test(p.loader||''))warnings.push('Install the matching mod loader on the client/server as required.');if(items.some(m=>/shader/i.test((m.kind||'')+' '+m.name)))warnings.push('Shader packs require a compatible client-side shader loader and graphics support.');if(items.some(m=>/geyser|floodgate/i.test(m.id+' '+m.name)))warnings.push('Geyser/Floodgate are server-side crossplay components; verify UDP ports and authentication configuration.');if(!items.length)warnings.push('This pack has no recognized selected items.');out.innerHTML='<h3>Checklist</h3><ul>'+warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul><p class="muted">'+items.length+' recognized item(s). Review each official project page for exact dependencies.</p>'}});
document.addEventListener('input',e=>{if(e.target.id==='builderModSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#builderModGrid .mod-option').forEach(x=>x.style.display=(x.dataset.search||'').includes(q)?'':'none')}if(e.target.id==='modSearch')filterModCatalog();if(e.target.id==='gameSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#gameGrid .game-card').forEach(c=>c.style.display=c.innerText.toLowerCase().includes(q)?'':'none')}if(e.target.id==='serverSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#serverGrid .server-card').forEach(c=>c.style.display=c.innerText.toLowerCase().includes(q)?'':'none')}});
document.getElementById('profileBtn').addEventListener('click',()=>go('account'));
go('home');